function HealthIcon({ name, size = 20, title, className = "", style }) {
  const icon = ICONS[name];
  if (!icon) return null;
  const [viewBox, paths] = icon;
  return (
    <svg
      viewBox={viewBox}
      width={size}
      height={size}
      fill="currentColor"
      className={"ecms-hicon " + className}
      style={style}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      {paths.map(([d, evenodd], i) => (
        <path key={i} d={d} fillRule={evenodd ? "evenodd" : undefined} clipRule={evenodd ? "evenodd" : undefined} />
      ))}
    </svg>
  );
}

export default HealthIcon;
